// Fixed BountyManager.sol
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../Interfaces/IBountyManager.sol";
import "../Interfaces/IReputationSystem.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title BountyManager
 * @dev Manages bounties for threat intelligence analysis in the Verdyx platform
 * @author Verdyx Team
 * @notice Uses a pull-payment (withdraw) pattern for all outbound token movement so
 *         that resolution never loops over external token transfers. This prevents
 *         gas-limit griefing/DoS where a single failing or gas-heavy recipient could
 *         block resolution and permanently lock staked funds.
 */


contract BountyManager is ReentrancyGuard {
    using SafeERC20 for IERC20;
    // Enums
    enum BountyStatus {
        Active,      // Bounty is open for submissions
        InReview,    // Analysis period has ended, consensus being calculated
        Completed,   // Bounty resolved with consensus
        Cancelled,   // Bounty cancelled by creator
        Disputed     // Bounty under dispute resolution
    }

    enum ThreatVerdict {
        Pending,    // No verdict yet
        Benign,     // File/URL is safe
        Malicious,  // File/URL is a threat
        Suspicious  // File/URL requires further investigation
    }

    // Structs
    struct Bounty {
        uint256 id;
        address creator;
        string artifactHash;
        string artifactType;
        uint256 rewardAmount;
        uint256 deadline;
        string description;
        BountyStatus status;
        ThreatVerdict consensusVerdict;
        uint256 totalStaked;
        uint256 analysisCount;
        uint256 createdAt;
    }

    struct Analysis {
        uint256 bountyId;
        address analyst;
        ThreatVerdict verdict;
        uint256 confidence;
        uint256 stakeAmount;
        string analysisHash;
        uint256 submittedAt;
        bool rewarded;
    }

    // state variables
    IERC20 public immutable threatToken;
    IReputationSystem public immutable reputationSystem;

    uint256 public bountyCounter;
    uint256 public constant MIN_STAKE_AMOUNT = 10 * 10**18;   // 10 token minimum stake
    uint256 public constant ANALYSIS_TIMEOUT = 24 hours;   // 24 hours to complete analysis
    uint256 public constant CONSENSUS_THRESHOLD = 66;   // 66% consensus required
    uint256 public constant PLATFORM_FEE_PERCENT = 5;    // 5% platfrom fee
    uint256 public constant MIN_ANALYSES_TO_RESOLVE = 5; // Synced threshold
    uint256 public constant MAX_ANALYSTS_PER_BOUNTY = 50; // Bounds resolution loops (gas-DoS guard)

    address public owner;
    address public feeCollector;
    bool public paused;

    // Mappings
    mapping(uint256 => Bounty) public bounties;
    mapping(uint256 => mapping(address => Analysis)) public analyses;
    mapping(uint256 => address[]) public bountyAnalysts;
    mapping(address => uint256[]) public userBounties;
    mapping(uint256 => mapping(address => uint256)) public analystSubmissionIds; // Reserved slot; currently unused (reputation handled at resolution)

    // Pull-payment ledger: funds owed to an account, claimed via withdraw()
    mapping(address => uint256) public pendingWithdrawals;

    // Events
    event BountyCreated(
        uint256 indexed bountyId,
        address indexed creator,
        string artifactHash,
        uint256 reward,
        uint256 deadline
    );

    event AnalysisSubmitted(
        uint256 indexed bountyId,
        address indexed engine,
        ThreatVerdict verdict,
        uint256 stake,
        uint256 confidence
    );

    event ConsensusReached(
        uint256 indexed bountyId,
        ThreatVerdict consensus,
        uint256 confidenceScore,
        uint256 totalAnalyses
    );

    event RewardsDistributed(
        uint256 indexed bountyId,
        address[] winners,
        uint256[] rewards,
        uint256[] stakes
    );

    event PaymentCredited(address indexed account, uint256 amount);

    event Withdrawal(address indexed account, uint256 amount);

    // Modifiers
    modifier onlyOwner() {
        require(msg.sender == owner, "Not authorized");
        _;
    }

    modifier notPaused() {
        require(!paused, "Contract is paused");
        _;
    }

    modifier validBounty(uint256 bountyId) {
        require(bountyId > 0 && bountyId <= bountyCounter, "Invalid bounty ID");
        _;
    }

    modifier bountyActive(uint256 bountyId) {
        require(bounties[bountyId].status == BountyStatus.Active, "Bounty not active");
        require(block.timestamp <= bounties[bountyId].deadline, "Bounty expired");
        _;
    }

    constructor(
        address _threatToken,
        address _reputationSystem,
        address _feeCollector
    ) {
        require(_threatToken != address(0), "Invalid token address");
        require(_reputationSystem != address(0), "Invalid reputation system address");
        require(_feeCollector != address(0), "Invalid fee collector address");

        threatToken = IERC20(_threatToken);
        reputationSystem = IReputationSystem(_reputationSystem);
        feeCollector = _feeCollector;
        owner = msg.sender;
    }

    /**
     * @dev Create a new bounty for threat analysis
     * @param artifactHash IPFS hash of the artifact to be analyzed
     * @param artifactType Type of artifact (file, URL, etc.)
     * @param rewardAmount Amount of tokens offered as reward
     * @param deadline Deadline for analysis submission
     * @param description Description of the bounty
     */

     function createBounty(
        string memory artifactHash,
        string memory artifactType,
        uint256 rewardAmount,
        uint256 deadline,
        string memory description
     ) external notPaused returns (uint256) {
        require(bytes(artifactHash).length > 0, "Invalid artifact hash");
        require(rewardAmount > 0, "Reward must be positive");
        require(deadline > block.timestamp + 1 hours, "Deadline too soon");
        require(bytes(description).length > 0, "Description required");

        // Transfer reward tokens to contract
        threatToken.safeTransferFrom(msg.sender, address(this), rewardAmount);

        bountyCounter++;

        bounties[bountyCounter] = Bounty({
            id: bountyCounter,
            creator: msg.sender,
            artifactHash: artifactHash,
            artifactType: artifactType,
            rewardAmount: rewardAmount,
            deadline: deadline,
            description: description,
            status: BountyStatus.Active,
            consensusVerdict: ThreatVerdict.Pending,
            totalStaked: 0,
            analysisCount: 0,
            createdAt: block.timestamp
        });

        userBounties[msg.sender].push(bountyCounter);

        emit BountyCreated(
            bountyCounter, 
            msg.sender, 
            artifactHash, 
            rewardAmount, 
            deadline
        );

        return bountyCounter;
     }

     /** 
     * @dev Submit analysis for a bounty
     * @param bountyId ID of the bounty
     * @param verdict Analysis verdict (Malicious/Benign)
     * @param confidence Confidence level (0-100)
     * @param stakeAmount Amount of tokens to stake
     * @param analysisHash IPFS hash of detailed analysis
     */

     function submitAnalysis(
        uint256 bountyId,
        ThreatVerdict verdict,
        uint256 confidence,
        uint256 stakeAmount,
        string memory analysisHash
     ) external nonReentrant validBounty(bountyId) bountyActive(bountyId) notPaused {
        require(verdict != ThreatVerdict.Pending, "Invalid verdict");
        require(confidence > 0 && confidence <= 100, "Invalid confidence");
        require(stakeAmount >= MIN_STAKE_AMOUNT, "Insufficient stake");
        require(bytes(analysisHash).length > 0, "Analysis hash required");
        require(analyses[bountyId][msg.sender].analyst == address(0), "Already submitted");
        require(
            bountyAnalysts[bountyId].length < MAX_ANALYSTS_PER_BOUNTY,
            "Analyst cap reached"
        );

        // Check reputation requirements
        require(
            reputationSystem.getReputation(msg.sender) >= reputationSystem.getMinimumReputation(),
            "Insufficient reputation"
        );

        // Effects: record the analysis before any external interaction
        analyses[bountyId][msg.sender] = Analysis({
            bountyId: bountyId,
            analyst: msg.sender,
            verdict: verdict,
            confidence: confidence,
            stakeAmount: stakeAmount,
            analysisHash: analysisHash,
            submittedAt: block.timestamp,
            rewarded: false
        });

        bountyAnalysts[bountyId].push(msg.sender);
        bounties[bountyId].totalStaked += stakeAmount;
        bounties[bountyId].analysisCount++;

        // Interaction: pull the stake into escrow
        threatToken.safeTransferFrom(msg.sender, address(this), stakeAmount);

        // NOTE: Reputation is intentionally NOT recorded at submission time.
        // Accuracy can only be judged once consensus is known, so all reputation
        // updates happen in _resolveBountyInternal() via
        // reputationSystem.updateReputationForAnalysis(). recordSubmission() is also
        // deliberately absent from the IReputationSystem interface this contract binds
        // to, so wiring it here is neither possible nor desirable.

        emit AnalysisSubmitted(
            bountyId,
            msg.sender,
            verdict,
            stakeAmount,
            confidence
        );

        // NOTE: Resolution is intentionally decoupled from submission. It is triggered
        // explicitly via resolveBounty() so that no single submitter is forced to pay
        // the gas to resolve on behalf of everyone, and so submission cost stays
        // bounded and predictable.
    }

    /**
     * @dev Resolve a bounty by determining consensus and distributing rewards
     * @param bountyId ID of the bounty to resolve
     */
    function resolveBounty(uint256 bountyId) 
        external 
        nonReentrant
        validBounty(bountyId) 
        notPaused 
    {
        Bounty storage bounty = bounties[bountyId];
        require(bounty.status == BountyStatus.Active, "Bounty not active");
        require(
            block.timestamp > bounty.deadline || bounty.analysisCount >= MIN_ANALYSES_TO_RESOLVE,
            "Cannot resolve yet"
        );

        _resolveBountyInternal(bountyId);
    }

    /**
     * @dev Internal function to resolve bounty and distribute rewards
     */
    function _resolveBountyInternal(uint256 bountyId) internal {
        Bounty storage bounty = bounties[bountyId];
        address[] storage analysts = bountyAnalysts[bountyId];

        if (analysts.length == 0) {
            // No analyses submitted, refund creator (via pull-payment)
            bounty.status = BountyStatus.Cancelled;
            _credit(bounty.creator, bounty.rewardAmount);
            return;
        }

        // Calculate consensus
        (ThreatVerdict consensus, uint256 consensusCount) = _calculateConsensus(bountyId);

        bounty.consensusVerdict = consensus;
        bounty.status = BountyStatus.Completed;

        // Update reputation for all analysts based on their analysis accuracy
        for (uint256 i = 0; i < analysts.length; i++) {
            address analyst = analysts[i];
            Analysis storage analysis = analyses[bountyId][analyst];

            // Check if analyst's verdict matches consensus
            bool wasCorrect = (analysis.verdict == consensus);

            // Update reputation in reputation system
            reputationSystem.updateReputationForAnalysis(
                analyst,
                bountyId,
                wasCorrect,
                analysis.stakeAmount
            );
        }

        // Distribute rewards and slash stakes
        _distributeRewards(bountyId, consensus, consensusCount);

        // Calculate confidence score (percentage of consensus)
        uint256 totalAnalyses = bountyAnalysts[bountyId].length;
        uint256 confidenceScore = totalAnalyses > 0 ? (consensusCount * 10000) / totalAnalyses : 0; // basis points

        emit ConsensusReached(bountyId, consensus, confidenceScore, totalAnalyses);
    }

    /**
     * @dev Calculate consensus from all analyses
     */
    function _calculateConsensus(uint256 bountyId) 
        internal 
        view 
        returns (ThreatVerdict consensus, uint256 consensusCount) 
    {
        address[] storage analysts = bountyAnalysts[bountyId];
        uint256 maliciousCount = 0;
        uint256 benignCount = 0;
        uint256 totalWeight = 0;

        for (uint256 i = 0; i < analysts.length; i++) {
            Analysis storage analysis = analyses[bountyId][analysts[i]];
            uint256 weight = analysis.stakeAmount * analysis.confidence / 100;
            totalWeight += weight;

            if (analysis.verdict == ThreatVerdict.Malicious) {
                maliciousCount += weight;
            } else if (analysis.verdict == ThreatVerdict.Benign) {
                benignCount += weight;
            }
        }

        if (totalWeight == 0) {
            return (ThreatVerdict.Pending, 0);
        }

        uint256 maliciousPercent = (maliciousCount * 100) / totalWeight;
        uint256 benignPercent = (benignCount * 100) / totalWeight;

        if (maliciousPercent >= CONSENSUS_THRESHOLD) {
            consensus = ThreatVerdict.Malicious;
            consensusCount = _countCorrectAnalyses(bountyId, ThreatVerdict.Malicious);
        } else if (benignPercent >= CONSENSUS_THRESHOLD) {
            consensus = ThreatVerdict.Benign;
            consensusCount = _countCorrectAnalyses(bountyId, ThreatVerdict.Benign);
        } else {
            consensus = ThreatVerdict.Pending; // No clear consensus
            consensusCount = 0;
        }
    }

    /**
     * @dev Count analyses that match the consensus
     */
    function _countCorrectAnalyses(uint256 bountyId, ThreatVerdict consensus) 
        internal 
        view 
        returns (uint256 count) 
    {
        address[] storage analysts = bountyAnalysts[bountyId];
        for (uint256 i = 0; i < analysts.length; i++) {
            if (analyses[bountyId][analysts[i]].verdict == consensus) {
                count++;
            }
        }
    }

    /**
     * @dev Distribute rewards to correct analysts and slash incorrect ones
     */
    function _distributeRewards(
        uint256 bountyId, 
        ThreatVerdict consensus, 
        uint256 winnerCount
    ) internal {
        Bounty storage bounty = bounties[bountyId];
        address[] storage analysts = bountyAnalysts[bountyId];

        uint256 totalRewardPool = bounty.rewardAmount;
        uint256 platformFee = (totalRewardPool * PLATFORM_FEE_PERCENT) / 100;
        uint256 rewardPool = totalRewardPool - platformFee;

        if (consensus == ThreatVerdict.Pending || winnerCount == 0) {
            // No consensus reached: refund creator minus platform fee, return stakes.
            // All amounts are credited for later withdrawal (no transfers in loops).
            uint256 refundAmount = totalRewardPool - platformFee;

            _credit(feeCollector, platformFee);
            _credit(bounty.creator, refundAmount);

            // Return stakes
            for (uint256 i = 0; i < analysts.length; i++) {
                address analyst = analysts[i];
                Analysis storage analysis = analyses[bountyId][analyst];
                _credit(analyst, analysis.stakeAmount);
            }
            return;
        }

        // Add slashed stakes to reward pool
        uint256 slashedAmount = _processSlashing(bountyId, consensus);
        rewardPool += slashedAmount;

        // Distribute rewards to winners
        uint256 individualReward = rewardPool / winnerCount;

        // Collect winners for event emission
        address[] memory winners = new address[](winnerCount);
        uint256[] memory rewards = new uint256[](winnerCount);
        uint256[] memory stakes = new uint256[](winnerCount);
        uint256 winnerIndex = 0;

        for (uint256 i = 0; i < analysts.length; i++) {
            address analyst = analysts[i];
            Analysis storage analysis = analyses[bountyId][analyst];

            if (analysis.verdict == consensus && !analysis.rewarded) {
                analysis.rewarded = true;

                // Credit stake + reward for later withdrawal
                uint256 totalPayout = analysis.stakeAmount + individualReward;
                _credit(analyst, totalPayout);

                // Collect for event
                winners[winnerIndex] = analyst;
                rewards[winnerIndex] = individualReward;
                stakes[winnerIndex] = analysis.stakeAmount;
                winnerIndex++;
            }
        }

        // Credit platform fee
        _credit(feeCollector, platformFee);

        // Emit rewards distributed event
        emit RewardsDistributed(bountyId, winners, rewards, stakes);
    }

    /**
     * @dev Credit an account's pull-payment balance. Funds are claimed via withdraw().
     */
    function _credit(address account, uint256 amount) internal {
        if (amount == 0) {
            return;
        }
        pendingWithdrawals[account] += amount;
        emit PaymentCredited(account, amount);
    }

    /**
     * @dev Withdraw funds owed to the caller (pull-payment pattern).
     * @notice This is the only path that moves tokens out of the contract to users,
     *         isolating external transfers from resolution so a single bad recipient
     *         cannot block everyone else.
     */
    function withdraw() external nonReentrant {
        uint256 amount = pendingWithdrawals[msg.sender];
        require(amount > 0, "Nothing to withdraw");

        // Effects before interaction
        pendingWithdrawals[msg.sender] = 0;

        threatToken.safeTransfer(msg.sender, amount);
        emit Withdrawal(msg.sender, amount);
    }

    /**
     * @dev Process slashing for incorrect analyses
     */
    function _processSlashing(uint256 bountyId, ThreatVerdict consensus)
        internal
        returns (uint256 totalSlashed)
    {
        address[] storage analysts = bountyAnalysts[bountyId];

        for (uint256 i = 0; i < analysts.length; i++) {
            address analyst = analysts[i];
            Analysis storage analysis = analyses[bountyId][analyst];

            if (analysis.verdict != consensus) {
                totalSlashed += analysis.stakeAmount;
                // Stakes are slashed (added to reward pool)
            }
        }
    }

    // View functions
    function getBounty(uint256 bountyId) 
        external 
        view 
        validBounty(bountyId) 
        returns (Bounty memory) 
    {
        return bounties[bountyId];
    }

    function getAnalysis(uint256 bountyId, address analyst) 
        external 
        view 
        validBounty(bountyId) 
        returns (Analysis memory) 
    {
        return analyses[bountyId][analyst];
    }

    function getBountyAnalysts(uint256 bountyId) 
        external 
        view 
        validBounty(bountyId) 
        returns (address[] memory) 
    {
        return bountyAnalysts[bountyId];
    }

    function getUserBounties(address user) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return userBounties[user];
    }

    function getTotalBounties() external view returns (uint256) {
        return bountyCounter;
    }

    // Admin functions
    function pause() external onlyOwner {
        paused = true;
    }

    function unpause() external onlyOwner {
        paused = false;
    }

    function setFeeCollector(address _feeCollector) external onlyOwner {
        require(_feeCollector != address(0), "Invalid fee collector");
        feeCollector = _feeCollector;
    }

    function emergencyWithdraw(address token, uint256 amount) external onlyOwner {
        require(paused, "Contract must be paused");
        if (token == address(0)) {
            payable(owner).transfer(amount);
        } else {
            IERC20(token).safeTransfer(owner, amount);
        }
    }
}

contracts/core/Governance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./ThreatToken.sol";

/**
 * @title Governance
 * @dev Decentralized governance system for Verdyx platform
 * @notice Allows token holders to propose and vote on platform changes
 */
contract Governance is AccessControl, ReentrancyGuard {

    // ============ STATE VARIABLES ============

    ThreatToken public immutable threatToken;

    bytes32 public constant PROPOSER_ROLE = keccak256("PROPOSER_ROLE");
    bytes32 public constant EXECUTOR_ROLE = keccak256("EXECUTOR_ROLE");

    uint256 public proposalCount;
    uint256 public constant VOTING_PERIOD = 3 days;
    uint256 public constant EXECUTION_DELAY = 1 days;
    uint256 public constant QUORUM_PERCENTAGE = 10; // 10% of total supply
    uint256 public constant PROPOSAL_THRESHOLD = 10000 * 10**18; // 10,000 tokens to propose

    // ============ ENUMS ============

    enum ProposalState {
        Pending,
        Active,
        Defeated,
        Succeeded,
        Queued,
        Executed,
        Cancelled
    }

    enum VoteType {
        Against,
        For,
        Abstain
    }

    // ============ STRUCTS ============

    struct Proposal {
        uint256 id;
        address proposer;
        string title;
        string description;
        address[] targets;
        uint256[] values;
        bytes[] calldatas;
        uint256 startTime;
        uint256 endTime;
        uint256 executionTime;
        uint256 forVotes;
        uint256 againstVotes;
        uint256 abstainVotes;
        ProposalState state;
        bool executed;
        bool cancelled;
    }

    struct Receipt {
        bool hasVoted;
        VoteType support;
        uint256 votes;
    }

    // ============ MAPPINGS ============

    mapping(uint256 => Proposal) public proposals;
    mapping(uint256 => mapping(address => Receipt)) public receipts;
    mapping(address => uint256[]) public userProposals;

    // ============ EVENTS ============

    event ProposalCreated(
        uint256 indexed proposalId,
        address indexed proposer,
        string title,
        uint256 startTime,
        uint256 endTime
    );

    event VoteCast(
        address indexed voter,
        uint256 indexed proposalId,
        VoteType support,
        uint256 votes
    );

    event ProposalQueued(
        uint256 indexed proposalId,
        uint256 executionTime
    );

    event ProposalExecuted(
        uint256 indexed proposalId
    );

    event ProposalCancelled(
        uint256 indexed proposalId
    );

    // ============ CONSTRUCTOR ============

    constructor(address _threatToken) {
        require(_threatToken != address(0), "Invalid token address");

        threatToken = ThreatToken(_threatToken);

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(PROPOSER_ROLE, msg.sender);
        _grantRole(EXECUTOR_ROLE, msg.sender);
    }

    // ============ PROPOSAL FUNCTIONS ============

    /**
     * @dev Create a new governance proposal
     * @param title Proposal title
     * @param description Detailed description
     * @param targets Target contract addresses
     * @param values ETH values for each call
     * @param calldatas Encoded function calls
     * @return Proposal ID
     */
    function propose(
        string memory title,
        string memory description,
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas
    ) external returns (uint256) {
        require(
            threatToken.balanceOf(msg.sender) >= PROPOSAL_THRESHOLD,
            "Insufficient tokens to propose"
        );
        require(targets.length > 0, "Must provide actions");
        require(targets.length == values.length, "Length mismatch");
        require(targets.length == calldatas.length, "Length mismatch");
        require(bytes(title).length > 0, "Title required");

        proposalCount++;
        uint256 proposalId = proposalCount;

        Proposal storage proposal = proposals[proposalId];
        proposal.id = proposalId;
        proposal.proposer = msg.sender;
        proposal.title = title;
        proposal.description = description;
        proposal.targets = targets;
        proposal.values = values;
        proposal.calldatas = calldatas;
        proposal.startTime = block.timestamp;
        proposal.endTime = block.timestamp + VOTING_PERIOD;
        proposal.state = ProposalState.Active;

        userProposals[msg.sender].push(proposalId);

        emit ProposalCreated(
            proposalId,
            msg.sender,
            title,
            proposal.startTime,
            proposal.endTime
        );

        return proposalId;
    }

    /**
     * @dev Cast a vote on a proposal
     * @param proposalId ID of the proposal
     * @param support Vote type (Against, For, Abstain)
     */
    function castVote(
        uint256 proposalId,
        VoteType support
    ) external nonReentrant {
        require(proposalId > 0 && proposalId <= proposalCount, "Invalid proposal");

        Proposal storage proposal = proposals[proposalId];
        require(proposal.state == ProposalState.Active, "Voting not active");
        require(block.timestamp <= proposal.endTime, "Voting ended");

        Receipt storage receipt = receipts[proposalId][msg.sender];
        require(!receipt.hasVoted, "Already voted");

        uint256 votes = threatToken.balanceOf(msg.sender);
        require(votes > 0, "No voting power");

        receipt.hasVoted = true;
        receipt.support = support;
        receipt.votes = votes;

        if (support == VoteType.For) {
            proposal.forVotes += votes;
        } else if (support == VoteType.Against) {
            proposal.againstVotes += votes;
        } else {
            proposal.abstainVotes += votes;
        }

        emit VoteCast(msg.sender, proposalId, support, votes);
    }

    /**
     * @dev Queue a successful proposal for execution
     * @param proposalId ID of the proposal
     */
    function queue(uint256 proposalId) external {
        require(proposalId > 0 && proposalId <= proposalCount, "Invalid proposal");

        Proposal storage proposal = proposals[proposalId];
        require(proposal.state == ProposalState.Active, "Proposal not active");
        require(block.timestamp > proposal.endTime, "Voting not ended");
        require(!proposal.executed, "Already executed");
        require(!proposal.cancelled, "Proposal cancelled");

        // Check if proposal succeeded
        uint256 totalVotes = proposal.forVotes + proposal.againstVotes + proposal.abstainVotes;
        uint256 quorum = (threatToken.totalSupply() * QUORUM_PERCENTAGE) / 100;

        if (totalVotes >= quorum && proposal.forVotes > proposal.againstVotes) {
            proposal.state = ProposalState.Succeeded;
            proposal.executionTime = block.timestamp + EXECUTION_DELAY;
            proposal.state = ProposalState.Queued;

            emit ProposalQueued(proposalId, proposal.executionTime);
        } else {
            proposal.state = ProposalState.Defeated;
        }
    }

    /**
     * @dev Execute a queued proposal
     * @param proposalId ID of the proposal
     */
    function execute(uint256 proposalId) external nonReentrant onlyRole(EXECUTOR_ROLE) {
        require(proposalId > 0 && proposalId <= proposalCount, "Invalid proposal");

        Proposal storage proposal = proposals[proposalId];
        require(proposal.state == ProposalState.Queued, "Not queued");
        require(block.timestamp >= proposal.executionTime, "Execution delay not met");
        require(!proposal.executed, "Already executed");

        proposal.executed = true;
        proposal.state = ProposalState.Executed;

        // Execute all actions
        for (uint256 i = 0; i < proposal.targets.length; i++) {
            (bool success, ) = proposal.targets[i].call{value: proposal.values[i]}(
                proposal.calldatas[i]
            );
            require(success, "Execution failed");
        }

        emit ProposalExecuted(proposalId);
    }

    /**
     * @dev Cancel a proposal (only by proposer or admin)
     * @param proposalId ID of the proposal
     */
    function cancel(uint256 proposalId) external {
        require(proposalId > 0 && proposalId <= proposalCount, "Invalid proposal");

        Proposal storage proposal = proposals[proposalId];
        require(
            msg.sender == proposal.proposer || hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "Not authorized"
        );
        require(!proposal.executed, "Already executed");
        require(!proposal.cancelled, "Already cancelled");

        proposal.cancelled = true;
        proposal.state = ProposalState.Cancelled;

        emit ProposalCancelled(proposalId);
    }

    // ============ VIEW FUNCTIONS ============

    /**
     * @dev Get proposal state
     * @param proposalId ID of the proposal
     * @return Current state of the proposal
     */
    function getProposalState(uint256 proposalId) external view returns (ProposalState) {
        require(proposalId > 0 && proposalId <= proposalCount, "Invalid proposal");
        return proposals[proposalId].state;
    }

    /**
     * @dev Get proposal details
     * @param proposalId ID of the proposal
     * @return Proposal struct
     */
    function getProposal(uint256 proposalId) external view returns (Proposal memory) {
        require(proposalId > 0 && proposalId <= proposalCount, "Invalid proposal");
        return proposals[proposalId];
    }

    /**
     * @dev Get vote receipt for a voter
     * @param proposalId ID of the proposal
     * @param voter Address of the voter
     * @return Receipt struct
     */
    function getReceipt(uint256 proposalId, address voter) external view returns (Receipt memory) {
        return receipts[proposalId][voter];
    }

    /**
     * @dev Get all proposals by a user
     * @param user Address of the user
     * @return Array of proposal IDs
     */
    function getUserProposals(address user) external view returns (uint256[] memory) {
        return userProposals[user];
    }

    /**
     * @dev Get voting power for an address
     * @param voter Address to check
     * @return Number of votes (token balance)
     */
    function getVotingPower(address voter) external view returns (uint256) {
        return threatToken.balanceOf(voter);
    }

    /**
     * @dev Get current quorum requirement
     * @return Quorum in tokens
     */
    function getQuorum() external view returns (uint256) {
        return (threatToken.totalSupply() * QUORUM_PERCENTAGE) / 100;
    }

    /**
     * @dev Check if a proposal has reached quorum
     * @param proposalId ID of the proposal
     * @return Whether quorum is reached
     */
    function hasReachedQuorum(uint256 proposalId) external view returns (bool) {
        require(proposalId > 0 && proposalId <= proposalCount, "Invalid proposal");

        Proposal storage proposal = proposals[proposalId];
        uint256 totalVotes = proposal.forVotes + proposal.againstVotes + proposal.abstainVotes;
        uint256 quorum = (threatToken.totalSupply() * QUORUM_PERCENTAGE) / 100;

        return totalVotes >= quorum;
    }

    // ============ ADMIN FUNCTIONS ============

    /**
     * @dev Grant proposer role to an address
     * @param account Address to grant role
     */
    function grantProposerRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        grantRole(PROPOSER_ROLE, account);
    }

    /**
     * @dev Revoke proposer role from an address
     * @param account Address to revoke role
     */
    function revokeProposerRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        revokeRole(PROPOSER_ROLE, account);
    }

    // ============ RECEIVE FUNCTION ============

    receive() external payable {}
}

contracts/core/ReputationSystem.sol.content:
// Fixed ReputationSystem.sol
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "../Interfaces/IReputationSystem.sol";

/**
 * @title ReputationSystem
 * @dev Manages reputation scores for security analysts and engines in the Verdyx platform
 * @notice This contract tracks accuracy, participation, and calculates weighted reputation scores
 */
contract ReputationSystem is IReputationSystem, AccessControl {

    bytes32 public constant BOUNTY_MANAGER_ROLE = keccak256("BOUNTY_MANAGER_ROLE");
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    // Constants for reputation calculations
    uint256 public constant INITIAL_REPUTATION = 100;
    uint256 public constant MAX_REPUTATION = 1000;
    uint256 public constant MIN_REPUTATION = 0;
    uint256 public constant ACCURACY_WEIGHT = 70; // 70% weight for accuracy
    uint256 public constant PARTICIPATION_WEIGHT = 20; // 20% weight for participation
    uint256 public constant CONSISTENCY_WEIGHT = 10; // 10% weight for consistency
    uint256 public constant DECAY_RATE = 5; // 5% decay per month for inactive users
    uint256 public constant MIN_SUBMISSIONS_FOR_RATING = 10;

    // Structs
    struct EngineProfile {
       bool isRegistered;
       uint8 engineType;
       uint256 reputation;
       uint256 totalSubmissions;
       uint256 correctPredictions;
       uint256 lastActiveTimestamp;
       uint256 registrationTimestamp;
       bool isActive;
        // Additional fields
       uint256 falsePositives;
       uint256 falseNegatives;
       uint256 totalStakeAmount;
       uint256 totalRewards;
       uint256 consecutiveCorrect;
       uint256 maxConsecutiveCorrect;
    }

    // ReputationRecord is defined in IReputationSystem interface

    struct SubmissionRecord {
        address engine;
        uint256 bountyId;
        bool prediction; // true for malicious, false for benign
        bool actualResult;
        uint256 stakeAmount;
        uint256 timestamp;
        bool isResolved;
        uint256 confidenceScore; // 0-100
    }

    struct ReputationTier {
        uint256 minReputation;
        uint256 maxStakeMultiplier;
        uint256 rewardBonus; // percentage bonus
        string tierName;
    }

    // EngineInfo is defined in IReputationSystem interface

    enum EngineCategory {
        Human,
        AutomatedEngine,
        HybridSystem
    }

    // State variables
    mapping(address => EngineProfile) public engines;
    mapping(uint256 => SubmissionRecord) public submissions;
    mapping(address => uint256[]) public engineSubmissions;
    mapping(uint256 => ReputationTier) public reputationTiers;
    mapping(address => ReputationRecord[]) private reputationHistory;
    mapping(address => uint256) public engineIndex;

    address[] public activeEngines;
    uint256 public nextSubmissionId;
    uint256 public totalActiveEngines;
    uint256 public decayTimestamp;

    // Events are defined in IReputationSystem interface

    event SubmissionRecorded(
        uint256 indexed submissionId,
        address indexed engineAddress,
        uint256 indexed bountyId,
        bool prediction,
        uint256 stakeAmount
    );

    event SubmissionResolved(
        uint256 indexed submissionId,
        bool isCorrect,
        uint256 reputationChange
    );

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);

        // Initialize reputation tiers
        _initializeReputationTiers();

        decayTimestamp = block.timestamp;
        nextSubmissionId = 1;
    }

    /**
    * @notice Check if an engine is eligible to participate in bounties
    */
    function isEligibleEngine(address engineAddress) 
        external 
        view 
        override 
        returns (bool) 
    {
        EngineProfile storage profile = engines[engineAddress];
        return profile.isActive && profile.reputation >= getMinimumReputation();
    }

    /**
    * @notice Get minimum reputation required to participate
    */
    function getMinimumReputation() 
        public 
        view 
        override 
        returns (uint256) 
    {
        return MIN_REPUTATION;
    }

    /**
    * @notice Get reputation decay parameters
    */
    function getDecayParameters() 
        external 
        view 
        override 
        returns (uint256 decayRate, uint256 decayPeriod) 
    {
        return (DECAY_RATE, 30 days);
    }

    /**
    * @notice Get reputation multipliers for different engine types
    */
    function getEngineMultiplier(uint8 engineType) 
        external 
        pure 
        override 
        returns (uint256) 
    {
        if (engineType == 0) return 100; // Human
        if (engineType == 1) return 80;  // Automated
        return 90; // Hybrid
    }

    function getEngineInfo(address engineAddress)
        external
        view
        returns (EngineInfo memory)
    {
        EngineProfile storage profile = engines[engineAddress];
        return EngineInfo({
            isRegistered: profile.isRegistered,
            engineType: profile.engineType,
            reputation: profile.reputation,
            totalAnalyses: profile.totalSubmissions,
            correctAnalyses: profile.correctPredictions,
            lastActivityTimestamp: profile.lastActiveTimestamp,
            registrationTimestamp: profile.registrationTimestamp,
            isActive: profile.isActive
        });
    }

    function registerEngine(address engineAddress, uint8 engineType) 
        external 
        override 
        onlyRole(BOUNTY_MANAGER_ROLE)
        returns (bool success) 
    {
        require(engineAddress != address(0), "Invalid engine address");
        require(!engines[engineAddress].isActive, "Engine already registered");
        require(engineType <= 2, "Invalid engine type");

        engines[engineAddress] = EngineProfile({
            isRegistered: true,
            engineType: engineType,
            reputation: INITIAL_REPUTATION,
            totalSubmissions: 0,
            correctPredictions: 0,
            lastActiveTimestamp: block.timestamp,
            registrationTimestamp: block.timestamp,
            isActive: true,
            falsePositives: 0,
            falseNegatives: 0,
            totalStakeAmount: 0,
            totalRewards: 0,
            consecutiveCorrect: 0,
            maxConsecutiveCorrect: 0
        });

        activeEngines.push(engineAddress);
        engineIndex[engineAddress] = activeEngines.length - 1;
        totalActiveEngines += 1;

        emit EngineRegistered(engineAddress, engineType, INITIAL_REPUTATION);
        return true;
    }

    function deactivateEngine(address engineAddress) 
        external
        override
        onlyRole(BOUNTY_MANAGER_ROLE)
        returns (bool success)
    {
        require(engines[engineAddress].isActive, "Engine not active");
        uint256 index = engineIndex[engineAddress];
        address last = activeEngines[activeEngines.length - 1];
        activeEngines[index] = last;
        engineIndex[last] = index;
        activeEngines.pop();
        delete engineIndex[engineAddress];
        engines[engineAddress].isActive = false;
        totalActiveEngines -= 1;
        return true;
    }

    function reactivateEngine(address engineAddress)
        external
        override
        onlyRole(BOUNTY_MANAGER_ROLE)
        returns (bool success) 
    {
        require(!engines[engineAddress].isActive, "Engine already active");
        engines[engineAddress].isActive = true;
        activeEngines.push(engineAddress);
        engineIndex[engineAddress] = activeEngines.length - 1;
        totalActiveEngines += 1;
        return true;
    }

    function penalizeEngine(
        address engineAddress, 
        uint256 penaltyAmount, 
        string calldata reason
    ) external override onlyRole(BOUNTY_MANAGER_ROLE) returns (bool success) {
        EngineProfile storage profile = engines[engineAddress];
        require(profile.isActive, "Engine not active");

        uint256 oldReputation = profile.reputation;
        if (profile.reputation > penaltyAmount) {
            profile.reputation -= penaltyAmount;
        } else {
            profile.reputation = MIN_REPUTATION;
        }

        reputationHistory[engineAddress].push(ReputationRecord({
            timestamp: block.timestamp,
            oldReputation: oldReputation,
            newReputation: profile.reputation,
            changeType: 1, // 1 = penalty
            bountyId: 0 // not tied to specific bounty
        }));

        emit EnginePenalized(engineAddress, penaltyAmount, reason);
        emit ReputationUpdated(engineAddress, oldReputation, profile.reputation, reason);
        return true;
    }

    function recordSubmission(
        address engine,
        uint256 bountyId,
        bool prediction,
        uint256 stakeAmount,
        uint256 confidenceScore
    ) external onlyRole(BOUNTY_MANAGER_ROLE) returns (uint256) {
        require(engines[engine].isActive, "Engine not active");
        require(confidenceScore <= 100, "Invalid confidence score");

        uint256 submissionId = nextSubmissionId++;

        submissions[submissionId] = SubmissionRecord({
            engine: engine,
            bountyId: bountyId,
            prediction: prediction,
            actualResult: false,
            stakeAmount: stakeAmount,
            timestamp: block.timestamp,
            isResolved: false,
            confidenceScore: confidenceScore
        });

        engineSubmissions[engine].push(submissionId);
        engines[engine].totalSubmissions += 1;
        engines[engine].totalStakeAmount += stakeAmount;
        engines[engine].lastActiveTimestamp = block.timestamp;

        emit SubmissionRecorded(submissionId, engine, bountyId, prediction, stakeAmount);
        return submissionId;
    }

    function resolveSubmission(uint256 submissionId, bool actualResult)
        external
        onlyRole(BOUNTY_MANAGER_ROLE)
    {
        SubmissionRecord storage submission = submissions[submissionId];
        require(!submission.isResolved, "Submission already resolved");
        require(submission.engine != address(0), "Invalid submission");

        submission.actualResult = actualResult;
        submission.isResolved = true;

        bool isCorrect = submission.prediction == actualResult;
        uint256 reputationChange = _updateEngineReputation(submission.engine, submissionId, isCorrect);

        emit SubmissionResolved(submissionId, isCorrect, reputationChange);
    }

    function updateReputation(address engine, bool success) external onlyRole(BOUNTY_MANAGER_ROLE) {
        // Wrapper for compatibility if needed, but prefer resolveSubmission
        EngineProfile storage profile = engines[engine];
        uint256 oldReputation = profile.reputation;
        uint256 change = success ? 10 : 5; // Example, adjust as needed
        if (success) {
            profile.reputation = (profile.reputation + change > MAX_REPUTATION) ? MAX_REPUTATION : profile.reputation + change;
        } else {
            profile.reputation = (profile.reputation > change) ? profile.reputation - change : MIN_REPUTATION;
        }
        emit ReputationUpdated(engine, oldReputation, profile.reputation, success ? "Success" : "Failure");
    }

    /**
     * @notice Update engine reputation based on analysis accuracy (interface implementation)
     * @param engineAddress Address of the engine
     * @param bountyId ID of the bounty being analyzed
     * @param wasCorrect Whether the engine's analysis was correct
     * @param stakeAmount Amount staked by the engine
     * @return newReputation Updated reputation score
     */
    function updateReputationForAnalysis(
        address engineAddress,
        uint256 bountyId,
        bool wasCorrect,
        uint256 stakeAmount
    ) external override onlyRole(BOUNTY_MANAGER_ROLE) returns (uint256 newReputation) {
        EngineProfile storage profile = engines[engineAddress];
        require(profile.isActive, "Engine not active");

        uint256 oldReputation = profile.reputation;

        // Calculate reputation change based on correctness and stake
        uint256 change;
        if (wasCorrect) {
            // Base gain + stake-based bonus
            change = 5 + (stakeAmount / 1000);
            if (change > 20) change = 20; // Cap gain
            profile.reputation = (profile.reputation + change > MAX_REPUTATION) ? MAX_REPUTATION : profile.reputation + change;
            profile.correctPredictions += 1;
        } else {
            // Base loss + stake-based penalty
            change = 10 + (stakeAmount / 500);
            if (change > 30) change = 30; // Cap loss
            profile.reputation = (profile.reputation > change) ? profile.reputation - change : MIN_REPUTATION;
        }

        profile.totalSubmissions += 1;
        profile.lastActiveTimestamp = block.timestamp;

        reputationHistory[engineAddress].push(ReputationRecord({
            timestamp: block.timestamp,
            oldReputation: oldReputation,
            newReputation: profile.reputation,
            changeType: wasCorrect ? uint8(0) : uint8(2), // 0 = reward, 2 = incorrect
            bountyId: bountyId
        }));

        emit ReputationUpdated(engineAddress, oldReputation, profile.reputation, wasCorrect ? "Correct analysis" : "Incorrect analysis");
        return profile.reputation;
    }

    /**
     * @notice Apply reputation decay for a specific inactive engine (interface implementation)
     * @param engineAddress Address of the engine
     * @return newReputation Updated reputation after decay
     */
    function applyReputationDecay(address engineAddress) external override onlyRole(ADMIN_ROLE) returns (uint256 newReputation) {
        EngineProfile storage profile = engines[engineAddress];
        require(profile.isRegistered, "Engine not registered");
        require(block.timestamp >= profile.lastActiveTimestamp + 30 days, "Decay not due yet");

        uint256 oldReputation = profile.reputation;
        uint256 decayAmount = profile.reputation * DECAY_RATE / 100;

        if (profile.reputation > decayAmount) {
            profile.reputation -= decayAmount;
        } else {
            profile.reputation = MIN_REPUTATION;
        }

        reputationHistory[engineAddress].push(ReputationRecord({
            timestamp: block.timestamp,
            oldReputation: oldReputation,
            newReputation: profile.reputation,
            changeType: 3, // 3 = decay
            bountyId: 0
        }));

        emit ReputationDecayed(engineAddress, decayAmount);
        emit ReputationUpdated(engineAddress, oldReputation, profile.reputation, "Reputation decay");

        return profile.reputation;
    }

    function _updateEngineReputation(address engine, uint256 submissionId, bool isCorrect) internal returns (uint256 reputationChange) {
        EngineProfile storage profile = engines[engine];
        SubmissionRecord storage submission = submissions[submissionId];

        uint256 oldReputation = profile.reputation;

        // Calculate components
        uint256 accuracyScore = _getAccuracyScore(engine);
        uint256 participationScore = _getParticipationScore(engine);
        uint256 consistencyScore = _getConsistencyScore(engine);

        // Weighted reputation base
        uint256 weightedBase = (accuracyScore * ACCURACY_WEIGHT + participationScore * PARTICIPATION_WEIGHT + consistencyScore * CONSISTENCY_WEIGHT) / 100;

        // Adjust for this submission
        reputationChange = isCorrect ? 
            _calculateReputationGain(engine, submissionId) : 
            _calculateReputationLoss(engine, submissionId);

        if (isCorrect) {
            profile.correctPredictions += 1;
            profile.consecutiveCorrect += 1;

            if (profile.consecutiveCorrect > profile.maxConsecutiveCorrect) {
                profile.maxConsecutiveCorrect = profile.consecutiveCorrect;
            }

            profile.reputation = (weightedBase + reputationChange > MAX_REPUTATION) ? MAX_REPUTATION : weightedBase + reputationChange;

        } else {
            profile.consecutiveCorrect = 0;

            if (submission.prediction && !submission.actualResult) {
                profile.falsePositives += 1;
            } else if (!submission.prediction && submission.actualResult) {
                profile.falseNegatives += 1;
            }

            profile.reputation = (weightedBase > reputationChange) ? weightedBase - reputationChange : MIN_REPUTATION;
        }

        reputationHistory[engine].push(ReputationRecord({
            timestamp: block.timestamp,
            oldReputation: oldReputation,
            newReputation: profile.reputation,
            changeType: isCorrect ? uint8(0) : uint8(2), // 0 = reward, 2 = incorrect prediction
            bountyId: submission.bountyId
        }));

        emit ReputationUpdated(engine, oldReputation, profile.reputation, isCorrect ? "Correct prediction" : "Incorrect prediction");
    }

    // Helper functions for weighted scores (added)
    function _getAccuracyScore(address engine) internal view returns (uint256) {
        EngineProfile storage profile = engines[engine];
        if (profile.totalSubmissions < MIN_SUBMISSIONS_FOR_RATING) return 50; // Default
        return (profile.correctPredictions * 100) / profile.totalSubmissions;
    }

    function _getParticipationScore(address engine) internal view returns (uint256) {
        EngineProfile storage profile = engines[engine];
        // Example: Scale based on submissions, cap at 100
        return profile.totalSubmissions > 100 ? 100 : profile.totalSubmissions;
    }

    function _getConsistencyScore(address engine) internal view returns (uint256) {
        EngineProfile storage profile = engines[engine];
        // Example: Based on consecutive correct, cap at 100
        return profile.maxConsecutiveCorrect > 100 ? 100 : profile.maxConsecutiveCorrect;
    }

    function _calculateReputationGain(address engine, uint256 submissionId) internal view returns (uint256) {
        EngineProfile memory profile = engines[engine];
        SubmissionRecord memory submission = submissions[submissionId];

        // Base gain
        uint256 baseGain = 5;

        // Confidence bonus (higher confidence = higher reward if correct)
        uint256 confidenceBonus = submission.confidenceScore / 20; // 0-5 bonus

        // Consistency bonus
        uint256 consistencyBonus = profile.consecutiveCorrect / 5; // Bonus for streaks

        // Stake-based bonus (higher stake = higher reward)
        uint256 stakeBonus = submission.stakeAmount / 1000; // Adjust divisor as needed
        if (stakeBonus > 10) stakeBonus = 10; // Cap at 10

        return baseGain + confidenceBonus + consistencyBonus + stakeBonus;
    }

    function _calculateReputationLoss(address engine, uint256 submissionId) internal view returns (uint256) {
        SubmissionRecord memory submission = submissions[submissionId];

        // Base loss
        uint256 baseLoss = 10;

        // Confidence penalty (higher confidence = higher penalty if wrong)
        uint256 confidencePenalty = submission.confidenceScore / 10; // 0-10 penalty

        // Stake-based penalty
        uint256 stakePenalty = submission.stakeAmount / 500; // Adjust divisor as needed
        if (stakePenalty > 15) stakePenalty = 15; // Cap at 15

        return baseLoss + confidencePenalty + stakePenalty;
    }

    function getReputation(address engine) external view override returns (uint256) {
        return engines[engine].reputation;
    }

    function getAccuracyRate(address engine) external view override returns (uint256) {
        EngineProfile memory profile = engines[engine];
        if (profile.totalSubmissions == 0) return 0;

        return profile.correctPredictions * 100 / profile.totalSubmissions;
    }

    function getEngineProfile(address engine) external view returns (EngineProfile memory) {
        return engines[engine];
    }

    function getAnalystTier(address engine) external view returns (uint256) {
        uint256 reputation = engines[engine].reputation;
        for (uint256 i = 4; i > 0; i--) {
            if (reputation >= reputationTiers[i].minReputation) return i;
        }
        return 0;
    }

    /**
     * @notice Apply reputation decay for all inactive engines (batch operation)
     * @dev This is a convenience function to apply decay to all engines at once
     */
    function applyReputationDecayAll() external onlyRole(ADMIN_ROLE) {
        require(block.timestamp >= decayTimestamp + 30 days, "Decay not due yet");

        for (uint256 i = 0; i < activeEngines.length; i++) {
            address engine = activeEngines[i];
            EngineProfile storage profile = engines[engine];

            if (block.timestamp >= profile.lastActiveTimestamp + 30 days) {
                uint256 oldReputation = profile.reputation;
                uint256 decayAmount = profile.reputation * DECAY_RATE / 100;
                if (profile.reputation > decayAmount) {
                    profile.reputation -= decayAmount;
                } else {
                    profile.reputation = MIN_REPUTATION;
                }

                reputationHistory[engine].push(ReputationRecord({
                    timestamp: block.timestamp,
                    oldReputation: oldReputation,
                    newReputation: profile.reputation,
                    changeType: 3, // 3 = decay
                    bountyId: 0 // not tied to specific bounty
                }));

                emit ReputationDecayed(engine, decayAmount);
            }
        }

        decayTimestamp = block.timestamp;
    }

    function _initializeReputationTiers() internal {
        reputationTiers[0] = ReputationTier(0, 100, 0, "Novice");
        reputationTiers[1] = ReputationTier(200, 150, 5, "Beginner");
        reputationTiers[2] = ReputationTier(400, 200, 10, "Intermediate");
        reputationTiers[3] = ReputationTier(600, 300, 20, "Advanced");
        reputationTiers[4] = ReputationTier(800, 500, 35, "Expert");
    }

    function getReputationTier(uint256 tier) external view returns (ReputationTier memory) {
        return reputationTiers[tier];
    }

    function getTopAnalysts(uint256 limit) external view returns (address[] memory) {
        require(limit > 0 && limit <= activeEngines.length, "Invalid limit");

        // NOTE: For efficiency, this could be improved with a better data structure, but kept as-is for now
        address[] memory sortedEngines = new address[](limit);

        for (uint256 i = 0; i < limit && i < activeEngines.length; i++) {
            address maxEngine = activeEngines[0];
            uint256 maxReputation = 0;

            for (uint256 j = 0; j < activeEngines.length; j++) {
                bool alreadySelected = false;
                for (uint256 k = 0; k < i; k++) {
                    if (sortedEngines[k] == activeEngines[j]) {
                        alreadySelected = true;
                        break;
                    }
                }

                if (!alreadySelected && engines[activeEngines[j]].reputation > maxReputation) {
                    maxEngine = activeEngines[j];
                    maxReputation = engines[activeEngines[j]].reputation;
                }
            }

            sortedEngines[i] = maxEngine;
        }

        return sortedEngines;
    }

    function getTotalAnalysts() external view returns (uint256) {
        return totalActiveEngines;
    }

    function isEligibleForTier(address engine, uint256 requiredTier) external view returns (bool) {
        uint256 currentTier = this.getAnalystTier(engine);
        return currentTier >= requiredTier;
    }

    function getReputationHistory(
        address engineAddress, uint256 limit
    ) external 
      view 
      override 
      returns (ReputationRecord[] memory records) 
    {
        require(limit > 0, "Invalid limit");
        uint256 histLen = reputationHistory[engineAddress].length;
        uint256 recLen = histLen < limit ? histLen : limit;
        records = new ReputationRecord[](recLen);
        uint256 start = histLen - recLen;
        for (uint256 i = 0; i < recLen; i++) {
            records[i] = reputationHistory[engineAddress][start + i];
        }
        return records;
    }

    function getTopEngines(
        uint256 limit
    ) external view override returns (
        address[] memory enginesList,
        uint256[] memory reputations
    ) {
        require(limit > 0 && limit <= activeEngines.length, "Invalid limit");

        enginesList = new address[](limit);
        reputations = new uint256[](limit);

        // NOTE: Same efficiency note as getTopAnalysts
        for (uint256 i = 0; i < limit && i < activeEngines.length; i++) {
            address maxEngine = activeEngines[0];
            uint256 maxReputation = 0;

            for (uint256 j = 0; j < activeEngines.length; j++) {
                bool alreadySelected = false;
                for (uint256 k = 0; k < i; k++) {
                    if (enginesList[k] == activeEngines[j]) {
                        alreadySelected = true;
                        break;
                    }
                }

                if (!alreadySelected && engines[activeEngines[j]].reputation > maxReputation) {
                    maxEngine = activeEngines[j];
                    maxReputation = engines[activeEngines[j]].reputation;
                }
            }

            enginesList[i] = maxEngine;
            reputations[i] = maxReputation;
        }
        return (enginesList, reputations);
    }

    function calculateRequiredStake(
        address engineAddress,
        uint256 baseStake
    ) external view override returns (uint256 requiredStake) {
        EngineProfile storage profile = engines[engineAddress];
        uint256 multiplier = this.getEngineMultiplier(profile.engineType);
        return (baseStake * multiplier) / 100;
    } 

    function rewardEngine(address engineAddress, uint256 rewardAmount, uint256 bountyId)
        external onlyRole(BOUNTY_MANAGER_ROLE) {
        EngineProfile storage profile = engines[engineAddress];
        profile.totalRewards += rewardAmount;
        emit EngineRewarded(engineAddress, rewardAmount, bountyId);
    }
}

contracts/core/ThreatToken.sol.content:
// SPDX-License-Identifier: MIT
// Fixed ThreatToken.sol
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Pausable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title ThreatToken
 * @dev ERC20 token for Verdyx threat intelligence marketplace
 * 
 * Features:
 * - Standard ERC20 functionality
 * - Burnable tokens for deflationary mechanics
 * - Pausable for emergency stops
 * - Role-based access control
 * - Staking mechanism for analysis engines
 * - Reward distribution for accurate threat detection
 * - Anti-manipulation safeguards
 */

contract ThreatToken is ERC20, ERC20Burnable, ERC20Pausable, AccessControl, ReentrancyGuard {
    // Roles
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant BOUNTY_MANAGER_ROLE = keccak256("BOUNTY_MANAGER_ROLE");
    bytes32 public constant REPUTATION_MANAGER_ROLE = keccak256("REPUTATION_MANAGER_ROLE");

    // Token Economics
    uint256 public constant MAX_SUPPLY = 1_000_000_000 * 10**18; // 1 billion tokens
    uint256 public constant INITIAL_SUPPLY = 100_000_000 * 10**18; // 100 million tokens

    // Staking Configuration
    uint256 public constant MIN_STAKE_AMOUNT = 100 * 10**18; // Minimum 100 tokens to stake
    uint256 public constant STAKE_LOCK_PERIOD = 24 hours; // 24 hours lock period
    uint256 public constant SLASH_PERCENTAGE = 10; // 10% slashing for incorrect analysis

    // Reward Configuration
    uint256 public constant BASE_REWARD_RATE = 5; // 5% base reward for correct analysis
    uint256 public constant BONUS_MULTIPLIER = 150; // 150% multiplier for first correct analysis

    // Structs
    struct Stake {
        uint256 amount;
        uint256 lockTime;
        bool active;
        address engine;
        bytes32 analysisId;
    }

    struct RewardPool {
        uint256 totalPool;
        uint256 distributed;
        mapping(address => uint256) engineRewards;
        bool finalized;
    }

    // State Variables
    mapping(address => Stake[]) public engineStakes;
    mapping(bytes32 => RewardPool) public analysisRewards;
    mapping(address => uint256) public totalStaked;
    mapping(address => uint256) public engineReputation;
    mapping(address => bool) public authorizedEngines;
    uint256 public globalActiveStakes; // Added for emergency recover tracking

    // Events
    event Staked(address indexed engine, uint256 amount, bytes32 indexed analysisId, uint256 stakeIndex);
    event Unstaked(address indexed engine, uint256 amount, bytes32 indexed analysisId, uint256 stakeIndex);
    event Slashed(address indexed engine, uint256 amount, bytes32 indexed analysisId, uint256 stakeIndex);
    event RewardDistributed(address indexed engine, uint256 amount, bytes32 indexed analysisId);
    event EngineAuthorized(address indexed engine, bool authorized);
    event ReputationUpdated(address indexed engine, uint256 newReputation);
    event TokensMinted(address indexed to, uint256 amount); // Added for mint transparency

    constructor(address admin) ERC20("ThreatToken", "THREAT") {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
        _grantRole(MINTER_ROLE, admin);
        _grantRole(BOUNTY_MANAGER_ROLE, admin);
        _grantRole(REPUTATION_MANAGER_ROLE, admin);

        // Mint initial supply to admin
        _mint(admin, INITIAL_SUPPLY);
    }

    /**
     * @dev Mint new tokens (up to max supply)
     * @param to Address to mint tokens to
     * @param amount Amount of tokens to mint
     */
    function mint(address to, uint256 amount) external onlyRole(MINTER_ROLE) {
        require(totalSupply() + amount <= MAX_SUPPLY, "Exceeds max supply");
        _mint(to, amount);
        emit TokensMinted(to, amount);
    }

    /**
     * @dev Pause all token transfers
     */
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /**
     * @dev Unpause all token transfers
     */
    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    /**
     * @dev Authorize or deauthorize an analysis engine
     * @param engine Address of the engine
     * @param authorized Whether the engine is authorized
     */
    function setEngineAuthorization(address engine, bool authorized) 
        external 
        onlyRole(REPUTATION_MANAGER_ROLE) 
    {
        authorizedEngines[engine] = authorized;
        emit EngineAuthorized(engine, authorized);
    }

    /**
     * @dev Stake tokens for analysis participation
     * @param amount Amount of tokens to stake
     * @param analysisId Unique identifier for the analysis
     */
    function stakeForAnalysis(uint256 amount, bytes32 analysisId) 
        external 
        nonReentrant 
        whenNotPaused 
    {
        require(authorizedEngines[msg.sender], "Engine not authorized");
        require(amount >= MIN_STAKE_AMOUNT, "Amount below minimum stake");
        require(balanceOf(msg.sender) >= amount, "Insufficient balance");

        // Transfer tokens to contract
        _transfer(msg.sender, address(this), amount);

        // Create stake record
        Stake memory newStake = Stake({
            amount: amount,
            lockTime: block.timestamp + STAKE_LOCK_PERIOD,
            active: true,
            engine: msg.sender,
            analysisId: analysisId
        });

        engineStakes[msg.sender].push(newStake);
        totalStaked[msg.sender] += amount;
        globalActiveStakes += amount; // Added

        uint256 stakeIndex = engineStakes[msg.sender].length - 1;
        emit Staked(msg.sender, amount, analysisId, stakeIndex);
    }

    /**
     * @dev Unstake tokens after lock period (if analysis allows)
     * @param stakeIndex Index of the stake to unstake
     */
    function unstake(uint256 stakeIndex) external nonReentrant whenNotPaused {
        require(stakeIndex < engineStakes[msg.sender].length, "Invalid stake index");

        Stake storage stake = engineStakes[msg.sender][stakeIndex];
        require(stake.active, "Stake not active");
        require(stake.engine == msg.sender, "Not stake owner");
        require(block.timestamp >= stake.lockTime, "Stake still locked");
        require(analysisRewards[stake.analysisId].finalized, "Analysis not finalized");

        uint256 amount = stake.amount;
        stake.active = false;
        totalStaked[msg.sender] -= amount;
        globalActiveStakes -= amount; // Added

        // Return tokens to engine
        _transfer(address(this), msg.sender, amount);

        emit Unstaked(msg.sender, amount, stake.analysisId, stakeIndex);
    }

    /**
     * @dev Slash tokens from incorrect analysis
     * @param engine Address of the engine to slash
     * @param stakeIndex Index of the stake to slash
     */
    function slashStake(address engine, uint256 stakeIndex) 
        external 
        onlyRole(BOUNTY_MANAGER_ROLE) 
        nonReentrant 
    {
        require(stakeIndex < engineStakes[engine].length, "Invalid stake index");

        Stake storage stake = engineStakes[engine][stakeIndex];
        require(stake.active, "Stake not active");

        uint256 slashAmount = (stake.amount * SLASH_PERCENTAGE) / 100;
        uint256 remainingAmount = stake.amount - slashAmount;

        stake.amount = remainingAmount;
        totalStaked[engine] -= slashAmount;
        globalActiveStakes -= slashAmount; // Added

        // Burn slashed tokens (deflationary mechanism)
        _burn(address(this), slashAmount);

        // Update reputation
        if (engineReputation[engine] > slashAmount) {
            engineReputation[engine] -= slashAmount;
        } else {
            engineReputation[engine] = 0;
        }

        emit Slashed(engine, slashAmount, stake.analysisId, stakeIndex);
        emit ReputationUpdated(engine, engineReputation[engine]);
    }

    /**
     * @dev Distribute rewards for correct analysis
     * @param analysisId Unique identifier for the analysis
     * @param correctEngines Array of engines that provided correct analysis
     * @param isFirstCorrect Array indicating which engines were first to be correct
     */
    function distributeRewards(
        bytes32 analysisId,
        address[] calldata correctEngines,
        bool[] calldata isFirstCorrect
    ) external onlyRole(BOUNTY_MANAGER_ROLE) nonReentrant {
        require(correctEngines.length == isFirstCorrect.length, "Array length mismatch");
        require(!analysisRewards[analysisId].finalized, "Rewards already distributed");

        RewardPool storage rewardPool = analysisRewards[analysisId];
        uint256 totalRewardsToMint = 0;

        // First pass: Calculate total to mint
        for (uint256 i = 0; i < correctEngines.length; i++) {
            address engine = correctEngines[i];
            uint256 baseReward = _calculateBaseReward(engine, analysisId);
            uint256 finalReward = baseReward;

            if (isFirstCorrect[i]) {
                finalReward = (baseReward * BONUS_MULTIPLIER) / 100;
            }

            rewardPool.engineRewards[engine] = finalReward;
            totalRewardsToMint += finalReward;
        }

        // Check total mint against max supply
        require(totalSupply() + totalRewardsToMint <= MAX_SUPPLY, "Exceeds max supply");

        // Second pass: Mint and distribute
        for (uint256 i = 0; i < correctEngines.length; i++) {
            address engine = correctEngines[i];
            uint256 finalReward = rewardPool.engineRewards[engine];

            // Update reputation
            engineReputation[engine] += finalReward;

            // Mint and transfer rewards
            _mint(engine, finalReward);
            emit RewardDistributed(engine, finalReward, analysisId);
            emit ReputationUpdated(engine, engineReputation[engine]);
        }

        rewardPool.totalPool = totalRewardsToMint;
        rewardPool.distributed = totalRewardsToMint;
        rewardPool.finalized = true;
    }

    /**
     * @dev Calculate base reward for an engine based on stake and reputation
     * @param engine Address of the engine
     * @param analysisId Analysis identifier
     * @return Base reward amount
     */
    function _calculateBaseReward(address engine, bytes32 analysisId) 
        internal 
        view 
        returns (uint256) 
    {
        uint256 stakedAmount = _getStakedAmountForAnalysis(engine, analysisId);
        uint256 reputationBonus = engineReputation[engine] / 1000; // 0.1% bonus per 1000 reputation

        uint256 baseReward = (stakedAmount * BASE_REWARD_RATE) / 100;
        uint256 bonusReward = (baseReward * reputationBonus) / 100;

        return baseReward + bonusReward;
    }

    /**
     * @dev Get staked amount for a specific analysis
     * @param engine Address of the engine
     * @param analysisId Analysis identifier
     * @return Total staked amount
     */
    function _getStakedAmountForAnalysis(address engine, bytes32 analysisId) 
        internal 
        view 
        returns (uint256) 
    {
        uint256 totalAmount = 0;
        Stake[] storage stakes = engineStakes[engine];

        for (uint256 i = 0; i < stakes.length; i++) {
            if (stakes[i].analysisId == analysisId && stakes[i].active) {
                totalAmount += stakes[i].amount;
            }
        }

        return totalAmount;
    }

    /**
     * @dev Get engine's stake information
     * @param engine Address of the engine
     * @return Array of active stake amounts and their analysis IDs
     */
    function getEngineStakes(address engine) 
        external 
        view 
        returns (Stake[] memory) 
    {
        return engineStakes[engine];
    }

    /**
     * @dev Get reward information for an analysis
     * @param analysisId Analysis identifier
     * @param engine Engine address
     * @return Reward amount for the engine
     */
    function getAnalysisReward(bytes32 analysisId, address engine) 
        external 
        view 
        returns (uint256) 
    {
        return analysisRewards[analysisId].engineRewards[engine];
    }

    /**
     * @dev Emergency function to recover stuck tokens
     * @param token Address of token to recover
     * @param amount Amount to recover
     */
    function emergencyRecover(address token, uint256 amount) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        if (token == address(this)) {
            // Only recover excess tokens not part of active stakes
            uint256 contractBalance = balanceOf(address(this));
            require(amount <= contractBalance - globalActiveStakes, "Cannot recover staked tokens");
        }

        if (token == address(0)) {
            payable(msg.sender).transfer(amount);
        } else {
            IERC20(token).transfer(msg.sender, amount);
        }
    }

    // Override functions for pausable functionality (OpenZeppelin v5)
    function _update(
        address from,
        address to,
        uint256 amount
    ) internal override(ERC20, ERC20Pausable) {
        super._update(from, to, amount);
    }
}

